class Solution {
public:
    int numUniqueEmails(vector<string>& emails) {
        unordered_set<string> seen;
        for (const string& email : emails) {
            string normalized;
            int n = email.size();
            int i = 0;
            while (i < n && email[i] != '@') {
                if (email[i] == '+') {
                    while (i < n && email[i] != '@') i++;
                    break;
                }
                if (email[i] != '.') {
                    normalized += email[i];
                }
                i++;
            }
            while (i < n) {
                normalized += email[i];
                i++;
            }
            seen.insert(normalized);
        }
        return seen.size();
    }
};
